-- Seed templates, settings, promo
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('web','web-ban-hang','Website bán hàng theo ngành','Quà tặng, đặc sản, OCOP, cà phê','Web bán hàng có giỏ hàng, COD, chuyển khoản VietQR tự xác nhận, phí ship, trang quản trị sản phẩm. Dựng trên Cloudflare, khách sở hữu mã nguồn.','https://dala-shop.sfportal.workers.dev',4900000,5,'[{"key":"brand","label":"Tên thương hiệu, logo, màu chủ đạo","question":"Tên cửa hàng, màu chủ đạo bạn muốn, và gửi logo (nếu có)?","required":true,"price":0},{"key":"products","label":"Danh sách sản phẩm (tối đa 30)","question":"Bạn có khoảng bao nhiêu sản phẩm, nhóm sản phẩm nào, giá khoảng bao nhiêu? Có file Excel hoặc ảnh không?","required":true,"price":0},{"key":"domain","label":"Tên miền","question":"Bạn đã có tên miền chưa? Nếu chưa, muốn dùng tên nào?","required":true,"price":0},{"key":"payment","label":"Tài khoản nhận tiền, cách giao hàng","question":"Số tài khoản ngân hàng nhận tiền, và bạn giao hàng bằng gì (tự giao, GoShip, COD)?","required":true,"price":0},{"key":"pages","label":"Trang nội dung thêm","question":"Ngoài trang sản phẩm, bạn cần thêm trang nào (giới thiệu, câu chuyện vùng trồng, chính sách đổi trả, blog)?","required":false,"price":0},{"key":"full","label":"Gói Đầy đủ: GoShip, flash sale, cộng tác viên, QR truy xuất","question":"Bạn có cần flash sale, cộng tác viên, báo giá quà doanh nghiệp, QR truy xuất lô hàng không?","required":false,"price":5000000},{"key":"inventory","label":"Nối tồn kho KiotViet/MISA","question":"Bạn có đang dùng KiotViet hoặc MISA và muốn nối tồn kho không?","required":false,"price":1500000}]','Fork mẫu dala-shop. Chỉ đổi: config thương hiệu (tên, logo, màu), dữ liệu sản phẩm, trang nội dung, tài khoản VietQR, phí ship. Không đổi cấu trúc giỏ hàng/thanh toán. Bật module Đầy đủ khi option full=yes.','## Hướng dẫn sử dụng website

1. **Đăng nhập quản trị:** mở `/admin` trên tên miền của bạn, đăng nhập bằng tài khoản đã gửi.
2. **Thêm sản phẩm:** Quản trị → Sản phẩm → Thêm, nhập tên, giá, ảnh, tồn kho.
3. **Xử lý đơn:** Quản trị → Đơn hàng. Đơn chuyển khoản tự chuyển sang "Đã thanh toán" khi tiền về.
4. **Mã nguồn:** repo GitHub đã chuyển quyền cho bạn; mọi thay đổi đẩy lên nhánh main sẽ tự deploy.
5. **Hỗ trợ:** nhắn Zalo 0938 266 958 kèm mã đơn.','#ff7a45',0);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('web','landing-du-an','Landing page dự án / chiến dịch','Bất động sản, sự kiện, khoá học','Một trang giới thiệu dự án hoặc chiến dịch: vị trí, bảng hàng, pháp lý, form nhận khách báo về Zalo.',NULL,1500000,3,'[{"key":"brand","label":"Tên dự án, logo, màu","question":"Tên dự án/chiến dịch, logo và màu chủ đạo?","required":true,"price":0},{"key":"sections","label":"Các khối nội dung","question":"Trang cần những khối nào: vị trí, tiện ích, bảng hàng, pháp lý, lịch sự kiện, cảm nhận khách?","required":true,"price":0},{"key":"lead_form","label":"Form nhận khách","question":"Form cần hỏi những gì, và gửi thông tin khách về đâu (Zalo, email, Google Sheet)?","required":true,"price":0},{"key":"table","label":"Bảng hàng / bảng giá cập nhật được","question":"Có cần bảng hàng hoặc bảng giá tự cập nhật không?","required":false,"price":500000}]','Dùng mẫu landing 1 trang. Đổi nội dung, màu, ảnh, khối hiển thị; form gửi về webhook của khách.','## Hướng dẫn sử dụng landing page

1. Link trang đã chạy ở tên miền bạn chọn.
2. Khách điền form sẽ báo về kênh bạn đã chọn.
3. Sửa nội dung: gửi yêu cầu cập nhật trong cổng khách hàng (100.000đ/lần) hoặc sửa file `content.json` trong repo GitHub.','#3d8bfd',1);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('web','mini-shop-menu','Mini-shop / Menu QR một trang','Shop nhỏ, quán cà phê, nhà hàng','Một trang gọn trên điện thoại: menu hoặc sản phẩm, đặt qua Zalo, mã VietQR, mã QR in đặt bàn.',NULL,990000,2,'[{"key":"brand","label":"Tên quán/shop, logo, màu","question":"Tên quán hoặc shop, màu chủ đạo, logo?","required":true,"price":0},{"key":"items","label":"Danh sách món/sản phẩm (tối đa 15)","question":"Gửi danh sách món hoặc sản phẩm kèm giá (tối đa 15), có ảnh thì càng tốt.","required":true,"price":0},{"key":"zalo","label":"Số Zalo nhận đặt hàng","question":"Số Zalo nhận đặt hàng/đặt bàn là số nào?","required":true,"price":0},{"key":"qr_print","label":"File in mã QR để bàn","question":"Bạn có cần file in mã QR để trên bàn không?","required":false,"price":0}]','Dùng mẫu mini-shop. Đổi dữ liệu món, màu, logo, số Zalo, tài khoản VietQR.','## Hướng dẫn sử dụng mini-shop

1. Chia sẻ link hoặc in mã QR đặt trên bàn/quầy.
2. Khách bấm "Đặt qua Zalo" sẽ mở chat với số Zalo của bạn kèm món đã chọn.
3. Cập nhật món: gửi yêu cầu trong cổng khách hàng.','#22c55e',2);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('extension','ext-zalo-cham-khach','Zalo Chăm Khách','Mọi ngành có tệp khách Zalo','Tiện ích Chrome chạy cùng Zalo Web: lọc khách trong nhóm, gắn nhãn, nhắc lịch, gửi tin chăm sóc kèm ảnh với nhịp an toàn.',NULL,1900000,3,'[{"key":"brand","label":"Tên hiển thị, biểu tượng","question":"Tên tiện ích hiển thị và logo/biểu tượng muốn dùng?","required":true,"price":0},{"key":"labels","label":"Bộ nhãn khách hàng","question":"Bạn muốn phân loại khách theo nhãn nào (mới, đã mua, VIP, lâu chưa quay lại, ...)?","required":true,"price":0},{"key":"templates","label":"Mẫu tin chăm sóc","question":"Bạn cần mẫu tin cho những dịp nào (cảm ơn, nhắc mua lại, Tết, sinh nhật, khuyến mãi)?","required":true,"price":0},{"key":"pace","label":"Nhịp gửi an toàn","question":"Mỗi ngày bạn muốn gửi tối đa khoảng bao nhiêu tin?","required":false,"price":0},{"key":"sheet","label":"Đồng bộ Google Sheet","question":"Có cần đồng bộ danh sách khách ra Google Sheet không?","required":false,"price":500000}]','Fork repo extension Zalo Chăm Khách. Đổi manifest (tên, icon), bộ nhãn mặc định, mẫu tin, giới hạn gửi. Không đổi lõi đọc DOM Zalo.','## Hướng dẫn cài và dùng extension

1. Tải file `.zip` trong mục Kết quả, giải nén.
2. Mở Chrome → `chrome://extensions` → bật **Chế độ nhà phát triển** → **Tải tiện ích đã giải nén** → chọn thư mục vừa giải nén.
3. Mở `chat.zalo.me`, đăng nhập, bấm biểu tượng tiện ích trên thanh công cụ.
4. Vào tab **Khách hàng** để gắn nhãn, tab **Chiến dịch** để gửi tin theo mẫu.
5. Giữ nhịp gửi mặc định để tránh bị Zalo hạn chế.','#0ea5e9',3);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('extension','ext-collector','Web & Fanpage Collector','Agency, bán hàng B2B','Tiện ích thu thập thông tin doanh nghiệp từ website và fanpage, chấm điểm kênh số, xuất danh sách khách tiềm năng.',NULL,1500000,3,'[{"key":"brand","label":"Tên hiển thị, biểu tượng","question":"Tên tiện ích và logo muốn dùng?","required":true,"price":0},{"key":"fields","label":"Trường dữ liệu cần lấy","question":"Bạn cần lấy những thông tin gì (tên, SĐT, email, địa chỉ, số follow, có web bán hàng không...)?","required":true,"price":0},{"key":"export","label":"Nơi xuất dữ liệu","question":"Xuất ra đâu: file Excel, Google Sheet hay gửi vào CRM?","required":true,"price":0},{"key":"scoring","label":"Thang chấm điểm riêng","question":"Có cần thang chấm điểm kênh số theo tiêu chí riêng không?","required":false,"price":500000}]','Fork repo Collector. Đổi manifest, danh sách trường, đích xuất dữ liệu, thang điểm.','## Hướng dẫn cài và dùng Collector

1. Tải `.zip`, giải nén, cài như mục "Tải tiện ích đã giải nén" trong Chrome.
2. Mở website hoặc fanpage cần lấy thông tin, bấm biểu tượng tiện ích → **Thu thập**.
3. Mở tab **Danh sách** để xem và **Xuất** ra nơi đã chọn.','#a855f7',4);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('media','media-reels','Video ngắn Reels / TikTok','Mọi ngành','Video 15 đến 30 giây khổ dọc 9:16 dựng từ ảnh có sẵn, có chữ, nhạc, lồng tiếng AI.',NULL,350000,1,'[{"key":"count","label":"Số video","question":"Bạn cần bao nhiêu video?","required":true,"price":0},{"key":"message","label":"Thông điệp, sản phẩm","question":"Mỗi video giới thiệu sản phẩm nào, thông điệp chính và lời kêu gọi là gì?","required":true,"price":0},{"key":"voice","label":"Giọng đọc","question":"Giọng đọc nam hay nữ, miền nào? Hay chỉ cần chữ và nhạc?","required":true,"price":0},{"key":"assets","label":"Ảnh/clip thô","question":"Bạn gửi ảnh hoặc clip sản phẩm được không (tải lên ở đây)?","required":true,"price":0},{"key":"brand_kit","label":"Khuôn thương hiệu dùng lại","question":"Bạn có muốn làm khuôn thương hiệu (màu, font, logo, giọng) để dùng lại cho mọi video sau không?","required":false,"price":1500000}]','Dùng bộ dựng video HTML → MP4 (render.js). Kịch bản 5-6 cảnh, chữ lớn, nhạc tự soạn, xuất 9:16.','## Hướng dẫn dùng video

1. Tải video MP4 trong mục Kết quả.
2. Đăng Reels/TikTok: chọn khổ 9:16, dán chú thích gợi ý kèm theo, gắn hashtag.
3. Giờ đăng nên chọn 11h-13h hoặc 19h-22h.','#ec4899',5);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('media','media-tvc','Video TVC 60 đến 90 giây','Thương hiệu, OCOP, sự kiện','Video giới thiệu thương hiệu có kịch bản, lồng tiếng, nhạc tự soạn, xuất 16:9 và 9:16 kèm phụ đề.',NULL,4000000,4,'[{"key":"goal","label":"Mục đích, người xem","question":"Video dùng để làm gì và người xem chính là ai?","required":true,"price":0},{"key":"points","label":"3 ý chính","question":"3 ý quan trọng nhất video phải nói là gì?","required":true,"price":0},{"key":"length","label":"Độ dài","question":"Bạn muốn 60 giây hay 90 giây?","required":true,"price":0},{"key":"assets","label":"Tư liệu","question":"Bạn có ảnh, clip, logo để gửi không?","required":true,"price":0},{"key":"long","label":"Bản 90 giây","question":"","required":false,"price":3000000}]','Dùng pipeline TVC (kịch bản → ảnh xem trước từng cảnh → lồng tiếng → render 16:9 và 9:16 + SRT).','## Hướng dẫn dùng TVC

1. Tải bản 16:9 cho YouTube/website, bản 9:16 cho Reels/TikTok, file phụ đề .srt.
2. Khi đăng YouTube, tải phụ đề lên mục Phụ đề.
3. Có thể cắt thành 3 video ngắn (600.000đ) qua cổng khách hàng.','#f59e0b',6);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('media','media-anh-ai','Ảnh sản phẩm AI','Shopee, TikTok Shop, Facebook','Tách nền, ghép bối cảnh theo mùa, banner đúng kích thước từng sàn, từ ảnh chụp điện thoại.',NULL,390000,1,'[{"key":"count","label":"Số ảnh","question":"Bạn cần bao nhiêu ảnh (gói 20 ảnh 390.000đ)?","required":true,"price":0},{"key":"scene","label":"Bối cảnh","question":"Bối cảnh mong muốn (Tết, Trung thu, tối giản, thiên nhiên...)?","required":true,"price":0},{"key":"channels","label":"Kênh đăng","question":"Ảnh dùng cho sàn/kênh nào để xuất đúng kích thước?","required":true,"price":0},{"key":"assets","label":"Ảnh gốc","question":"Tải lên ảnh sản phẩm chụp bằng điện thoại.","required":true,"price":0}]','Tách nền, ghép bối cảnh, xuất theo kích thước kênh.','## Hướng dẫn dùng ảnh

Ảnh đã xuất đúng kích thước từng kênh trong thư mục cùng tên. Tải về và đăng trực tiếp.','#14b8a6',7);
INSERT INTO templates (kind,slug,name,industries,summary,demo_url,base_price,days,options,claude_notes,guide_md,accent,sort) VALUES ('media','media-catalogue','Catalogue / bảng giá PDF','Quà tặng, B2B, đại lý','Catalogue sản phẩm, set quà dàn trang theo nhận diện, bản PDF gửi Zalo và bản in.',NULL,1800000,3,'[{"key":"pages","label":"Số trang (tối thiểu 12)","question":"Catalogue khoảng bao nhiêu trang (tối thiểu 12, 150.000đ/trang)?","required":true,"price":0},{"key":"products","label":"Danh sách sản phẩm, giá","question":"Gửi danh sách sản phẩm kèm giá (Excel hoặc ảnh chụp).","required":true,"price":0},{"key":"bilingual","label":"Song ngữ","question":"Có cần song ngữ không?","required":false,"price":600000},{"key":"print","label":"Bản in","question":"Có cần file in (bleed, CMYK) không?","required":false,"price":0}]','Dàn trang HTML → PDF theo bộ build catalogue TTN.','## Hướng dẫn dùng catalogue

1. Bản PDF nhẹ để gửi Zalo, bản in gửi nhà in.
2. Cập nhật mùa sau bằng 30% phí cũ qua cổng khách hàng.','#8b5cf6',8);
