INSERT INTO settings (key,value) VALUES ('support_kb','Salefronts làm 3 loại sản phẩm số cho SME: Media (video Reels, TVC, ảnh sản phẩm AI, catalogue), Extension Chrome (Zalo Chăm Khách, Collector) và Web (web bán hàng, landing page, mini-shop/menu QR). Quy trình: 1) điền SĐT Zalo, họ tên, ngành, công ty; 2) chọn loại và mẫu; 3) chat với AI để chốt yêu cầu; 4) xem mockup, sửa tối đa 2 lần; 5) đăng ký tài khoản và thanh toán VietQR; 6) Salefronts duyệt và thực hiện; 7) nhận kết quả kèm hướng dẫn trong mục Tài khoản > Đơn của tôi. Đơn từ 5 triệu cọc 50%. Tư vấn AI 60 phút giá 2.000.000đ, trừ vào đơn nếu đặt làm trong 14 ngày. Hotline/Zalo 0938 266 958, email admin@salefronts.com. Giới thiệu bạn bè: người giới thiệu nhận 10% đơn đã giao, người được giới thiệu giảm 5% đơn đầu.');
INSERT INTO promos (code,type,value,max_uses,note) VALUES ('TET2027','pct',10,200,'Khuyến mãi mùa Tết');
